cpp.setup:
auto* control = new fluent::collections::Transfer(%PARENT%);
control->setSourceHeader(QStringLiteral("Available members"));
control->setTargetHeader(QStringLiteral("Project members"));
control->setSearchPlaceholderText(QStringLiteral("Search members"));
auto* model = new QStandardItemModel(control);
for (const auto& entry : {QPair<QString, QString>{QStringLiteral("Lin Zhou"), QStringLiteral("Design systems")}, {QStringLiteral("Maya Ortiz"), QStringLiteral("Accessibility")}, {QStringLiteral("Noah Kim"), QStringLiteral("Release engineering")}, {QStringLiteral("Elena Rostova"), QStringLiteral("Documentation")}, {QStringLiteral("Ava Patel"), QStringLiteral("QA automation")}}) {
    auto* item = new QStandardItem(entry.first);
    item->setData(entry.first, Qt::UserRole);
    item->setData(entry.second, Qt::UserRole + 1);
    model->appendRow(item);
}
control->setModel(model);
control->setDescriptionRole(Qt::UserRole + 1);
control->setSelectedKeys({QStringLiteral("Lin Zhou"), QStringLiteral("Elena Rostova")});
